var savedMsgs=[];
try{var _r=localStorage.getItem(MSGS_KEY);if(_r){savedMsgs=JSON.parse(_r)||[]}}catch(e){savedMsgs=[]}
if(!Array.isArray(savedMsgs))savedMsgs=[];

